// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address payable actor, uint256 targetBlock) public {
        vm.assume(actor != address(0));
        targetBlock = bound(targetBlock, 1, 1_000_000);

        uint256 alignedBlock = targetBlock + ((15 - (targetBlock % 15)) % 15);
        vm.roll(alignedBlock);

        vm.warp(block.timestamp + 1);

        uint256 sendAmt = 10 ether;
        vm.deal(actor, sendAmt);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: sendAmt}('');
        vm.assume(ok);

        if (alignedBlock % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance >= 0);
        }
    }
}
